const fs = require('fs');

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const config = JSON.parse(fs.readFileSync('config.json', 'utf8'));
const result = { ...DEFAULTS, ...config };

fs.writeFileSync('config.out.json', JSON.stringify(result, null, 2) + '\n');
console.log('wrote config.out.json:', JSON.stringify(result));

